using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.ML.Transforms;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

// --- Train the model at startup and save it ---
var mlContext = new MLContext(seed: 42);
mlContext.ComponentCatalog.RegisterAssembly(typeof(ChurnLabelMappingFactory).Assembly);

var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "customers.csv");

var dataView = mlContext.Data.LoadFromTextFile<ChurnInput>(
    dataPath, hasHeader: true, separatorChar: ',');

var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);

var pipeline = mlContext.Transforms.CustomMapping(
        new ChurnLabelMappingFactory().GetMapping(), "ChurnLabelMapping")
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(ChurnInput.Region)))
    .Append(mlContext.Transforms.NormalizeMinMax(nameof(ChurnInput.Age)))
    .Append(mlContext.Transforms.NormalizeMinMax(nameof(ChurnInput.Income)))
    .Append(mlContext.Transforms.NormalizeMinMax(nameof(ChurnInput.PurchaseHistory)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(ChurnInput.Age), nameof(ChurnInput.Income),
        nameof(ChurnInput.PurchaseHistory), "RegionEncoded"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

var model = pipeline.Fit(split.TrainSet);

// Evaluate on test set
var predictions = model.Transform(split.TestSet);
try
{
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
    Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, " +
                      $"Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
}
catch (ArgumentOutOfRangeException)
{
    Console.WriteLine("Model trained — test set too small for full evaluation. Add more data for reliable metrics.");
}

var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "churn-model.zip");
mlContext.Model.Save(model, dataView.Schema, modelPath);

// Register the pooled prediction engine (thread-safe for ASP.NET Core)
builder.Services.AddPredictionEnginePool<ChurnInput, ChurnOutput>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST /predict with {age, income, region, purchaseHistory}");

app.MapPost("/predict", (PredictionEnginePool<ChurnInput, ChurnOutput> pool, ChurnRequest req) =>
{
    var input = new ChurnInput
    {
        Age = req.Age,
        Income = req.Income,
        Region = req.Region,
        PurchaseHistory = req.PurchaseHistory
    };
    var result = pool.Predict(input);
    return Results.Ok(new
    {
        willChurn = result.PredictedLabel,
        probability = result.Probability,
        score = result.Score
    });
});

app.Run();

// --- Data models ---

public class ChurnInput
{
    [LoadColumn(0)] public float Age { get; set; }
    [LoadColumn(1)] public float Income { get; set; }
    [LoadColumn(2)] public string Region { get; set; } = "";
    [LoadColumn(3)] public float PurchaseHistory { get; set; }
    [LoadColumn(4)] public string Churned { get; set; } = "";
}

public class ChurnOutput
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }
    public float Probability { get; set; }
    public float Score { get; set; }
}

public class ChurnLabel
{
    public bool Label { get; set; }
}

[CustomMappingFactoryAttribute("ChurnLabelMapping")]
public class ChurnLabelMappingFactory : CustomMappingFactory<ChurnInput, ChurnLabel>
{
    public override Action<ChurnInput, ChurnLabel> GetMapping()
        => (input, output) => output.Label = input.Churned == "Yes";
}

public record ChurnRequest(float Age, float Income, string Region, float PurchaseHistory);

